tmp_path = PosixPath('/tmp/pytest-of-root/pytest-0/test_paged_forward_matches_tra0') overrides = {}
@pytest.mark.parametrize("overrides", HF_PARITY_CASES.values(), ids=HF_PARITY_CASES) def test_paged_forward_matches_transformers_llama(tmp_path, overrides): hf_model, path = _save_tiny_hf_llama(tmp_path, **overrides) model = _load_nano(path) block_size = 4 cache = model.new_paged_cache(num_blocks=8, block_size=block_size) seq_a = [5, 17, 3, 88, 42, 9, 61, 2, 33, 70, 11] # blocks 0, 1, 2 seq_b = [7, 7, 50, 1, 95] # blocks 3, 4 tables = {"a": [0, 1, 2], "b": [3, 4]}
def slots(table, positions): return [table[p // block_size] * block_size + p % block_size for p in positions]
def run(segments): """segments: list of (name, tokens, start_position).""" input_ids, positions, slot_mapping, context_lens, query_lens = [], [], [], [], [] for name, tokens, start in segments: pos = list(range(start, start + len(tokens))) input_ids += tokens positions += pos slot_mapping += slots(tables[name], pos) context_lens.append(start + len(tokens)) query_lens.append(len(tokens)) max_blocks = max(len(tables[name]) for name, _, _ in segments) block_tables = [ tables[name] + [-1] * (max_blocks - len(tables[name])) for name, _, _ in segments ] return model.forward_paged( input_ids=torch.tensor(input_ids), positions=torch.tensor(positions), cache=cache, slot_mapping=torch.tensor(slot_mapping), block_tables=torch.tensor(block_tables), context_lens=torch.tensor(context_lens), query_lens=query_lens, is_prefill=True, )
# Chunked prefill of A (5 tokens) batched with all of B, then A's rest. first = run([("a", seq_a[:5], 0), ("b", seq_b, 0)]) second = run([("a", seq_a[5:], 5)]) # One decode step for both sequences in the same batch. decode = run([("a", [25], len(seq_a)), ("b", [60], len(seq_b))])
expected_a = _hf_logits(hf_model, seq_a + [25]) expected_b = _hf_logits(hf_model, seq_b + [60]) tol = dict(rtol=1e-5, atol=1e-5) > torch.testing.assert_close(first[:5], expected_a[:5], **tol) E AssertionError: Tensor-likes are not close! E E Mismatched elements: 361 / 480 (75.2%) E Greatest absolute difference: 0.0006644725799560547 at index (4, 51) (up to 1e-05 allowed) E Greatest relative difference: 0.1716008484363556 at index (4, 17) (up to 1e-05 allowed)
tests/unit/test_nano_vllm_model.py:260: AssertionError

